parameters.jsCode:
// Datos del agente
const datos = $('AI Agent').first().json.output;

// Ajustar texto para igualar nombres 
const normalizar = (texto) =>
  String(texto ?? '')
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/[\s-]/g, '');

const tarifas = $input.all().map(item => item.json);

let resultado = {
  tarifa_encontrada: false,
  prima: 0,
  version: '',
  detalle: ''
};

if (datos.estado !== 'COMPLETA') {
  resultado.detalle = 'Cotización incompleta: no se calcula prima';
} else {
  const anio = Number(datos.anio);

  // Busca el registro de marca, modelo y el año
  const fila = tarifas.find(t =>
    normalizar(t['Marca']) === normalizar(datos.marca) &&
    normalizar(t['Modelo']) === normalizar(datos.modelo) &&
    anio >= Number(t['Año desde']) &&
    anio <= Number(t['Año hasta'])
  );

  if (fila) {
    resultado = {
      tarifa_encontrada: true,
      prima: Number(fila['Precio']),
      version: fila['Versión'],
      detalle: 'Tarifa encontrada'
    };
  } else {
    // Diferencia entre el modelo y el año fuera de rango
    const existeModelo = tarifas.some(t =>
      normalizar(t['Marca']) === normalizar(datos.marca) &&
      normalizar(t['Modelo']) === normalizar(datos.modelo)
    );
    resultado.detalle = existeModelo
      ? `El año ${anio} está fuera del rango tarifado para este modelo`
      : 'La marca o el modelo no tienen tarifa';
  }
}

return [{ json: resultado }];
